%pyspark

# Function to parse an RDD using a specified delimiter
def parse_rdd(rdd, delimiter):
    # Split each record into individual fields
    return rdd.map(lambda x: x.split(delimiter))

# Function to display sample records and total record count
def preview_rdd(rdd, dataset_name):
    print("First 3 Parsed {} Records:".format(dataset_name))
    for record in rdd.take(3):
        print(record)
    print("\nTotal {} Records: {}".format(dataset_name, rdd.count()))

%sh

cqlsh -k movielen -e "

DROP TABLE IF EXISTS average_rating;
CREATE TABLE average_rating (
    movie_id INT PRIMARY KEY,
    average_rating DOUBLE
);

DROP TABLE IF EXISTS top10_movie;
CREATE TABLE top10_movie (
    movie_title TEXT PRIMARY KEY,
    rating_count INT,
    average_rating DOUBLE
);

DROP TABLE IF EXISTS active_favourite_genre;
CREATE TABLE active_favourite_genre (
    user_id INT PRIMARY KEY,
    total_movies_rated INT,
    favorite_genre TEXT
);

DROP TABLE IF EXISTS young_users;
CREATE TABLE young_users (
    user_id INT PRIMARY KEY,
    age INT,
    gender TEXT,
    occupation TEXT
);

DROP TABLE IF EXISTS scientist_users;
CREATE TABLE scientist_users (
    user_id INT PRIMARY KEY,
    age INT,
    gender TEXT,
    occupation TEXT
);
"

